@import './styles/tokens.css';

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html, body, #root {
  height: 100%;
  font-family: var(--font);
  color: var(--ink);
  background: var(--surface-muted);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

a { color: inherit; text-decoration: none; }

input, textarea {
  font-family: inherit;
  font-size: 16px;
}

.app-shell {
  min-height: 100%;
  max-width: 480px;
  margin: 0 auto;
  background: var(--surface-muted);
  position: relative;
  box-shadow: 0 0 60px rgba(11, 18, 32, 0.08);
  overflow: hidden;
}

.desktop-frame {
  min-height: 100vh;
  background: linear-gradient(160deg, #1a0f2e 0%, #2d1b4e 40%, #1a1208 100%);
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

@media (min-width: 900px) {
  .desktop-frame {
    flex-direction: row;
    justify-content: center;
    align-items: flex-start;
    gap: 32px;
    padding: 40px;
  }
  .app-shell {
    min-height: calc(100vh - 80px);
    height: calc(100vh - 80px);
    overflow: hidden;
    border-radius: 28px;
    border: 1px solid rgba(255,255,255,0.08);
  }
}

/* Pressable scale — prefer CSS transition over jank */
.pressable {
  transition: transform 180ms var(--ease-soft), opacity 180ms var(--ease-soft), box-shadow 220ms var(--ease-soft);
  will-change: transform;
  -webkit-tap-highlight-color: transparent;
}
.pressable:active {
  transform: scale(0.97);
}
.pressable:disabled {
  transform: none;
  cursor: not-allowed;
}

/* Route / tab fades */
.fade-in {
  animation: fadeIn 320ms var(--ease-out) both;
}
.route-fade {
  animation: routeFade 280ms var(--ease-soft) both;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes routeFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Springy sheet + modal */
@keyframes sheetUp {
  from { transform: translateY(36px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
@keyframes modalIn {
  from { opacity: 0; transform: scale(0.94) translateY(8px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.sheet {
  border-radius: var(--radius-sheet) var(--radius-sheet) 0 0;
  box-shadow: var(--shadow-sheet);
  background: var(--surface);
  animation: sheetUp 420ms var(--ease-spring) both;
}
.sheet-handle {
  width: 40px;
  height: 4px;
  border-radius: 2px;
  background: var(--border);
  margin: 0 auto 14px;
}
.modal-card {
  border-radius: var(--radius-sheet);
  box-shadow: var(--shadow-modal);
  animation: modalIn 380ms var(--ease-spring) both;
}

/* Blur tab bar */
.tab-bar {
  position: sticky;
  bottom: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: blur(20px) saturate(1.4);
  -webkit-backdrop-filter: blur(20px) saturate(1.4);
  border-top: 1px solid rgba(230, 232, 236, 0.7);
  padding-bottom: var(--safe-bottom);
  z-index: 40;
}
.tab-item {
  padding: 10px 4px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  font-size: 11;
  font-weight: 500;
  color: var(--ink-tertiary);
  transition: color 200ms var(--ease-soft), transform 180ms var(--ease-soft);
}
.tab-item.active {
  color: var(--orange);
  font-weight: 600;
}
.tab-item:active {
  transform: scale(0.94);
}

